std::filesystem::path normalize_path(const std::filesystem::path& input) {
  std::vector<path> parts;
  for (auto& part : input) {
    if (part == ".") continue;
    if (part == ".." && !parts.empty()) parts.pop_back(); else parts.push_back(part);
  }
  return join(parts);
}

